import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  const root = new Group();
  root.position.fromArray(config.scenePosition || [0, 0, 0]);
  if (config.sceneRotation) root.rotation.fromArray(config.sceneRotation);
  if (config.sceneScale) root.scale.fromArray(config.sceneScale);

  // Create backdrop plane: 7×6 units at z=-2.5
  const backdropGeo = new PlaneGeometry(7, 6);

  // Build vertical gradient from visualSpec colors
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Engineered gradient: surface (dark) → ink (deep black) with subtle accent undertone
  const surfaceVec = vec3(0.043, 0.043, 0.063); // #0b0b10
  const inkVec = vec3(0.086, 0.086, 0.114);    // #16161d

  // Create gradient using uv coordinates (v goes 0→1 top→bottom)
  const gradientNode = mix(surfaceVec, inkVec, uv().y);

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    transparent: false
  });

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = 0;
  root.add(backdrop);

  // Load the image texture for the plane
  const planeGeo = new PlaneGeometry(2.6, 1.6); // Aspect 512:320 ≈ 1.6:1
  let planeMat = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true
  });

  const plane = new Mesh(planeGeo, planeMat);
  plane.position.z = 0;
  plane.renderOrder = 10;
  root.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // Render "Pricing" headline text using fontAtlas
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let headlineText = 'Pricing';

  for (const item of textItems) {
    if (item.role === 'headline') {
      headlineText = String(item.text);
      break;
    }
  }

  const headlineObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: 96,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 400,
    letterSpacingPx: 0
  });

  headlineObj.position.set(0, 0.8, 1);
  headlineObj.scale.multiplyScalar(0.01); // Convert from pixel space to scene units
  root.add(headlineObj);

  // Cleanup function
  root.userData.cleanup = () => {
    backdropMat.dispose();
    backdropGeo.dispose();
    planeMat.dispose();
    planeGeo.dispose();
    if (planeMat.map) planeMat.map.dispose();
  };

  root.userData.handlers = {};

  return root;
}
